      const gr = g.createLinearGradient(0, 0, 0, h); gr.addColorStop(0, '#5a3aa8'); gr.addColorStop(0.6, '#8a6ad8'); gr.addColorStop(1, '#6a4ab8'); g.fillStyle = gr; g.fillRect(0, 0, w, h);
