        g.fillStyle = tone(c, 0.86 + ((((x + 128) / 32 + y / 32) % 4)) * 0.05); g.fillRect(x, y, 128, 32);
        g.strokeStyle = 'rgba(40,50,70,0.2)'; g.lineWidth = 1; for (let i = 0; i < 3; i++) { const gy = y + 8 + i * 8; g.beginPath(); g.moveTo(x + 4, gy); g.bezierCurveTo(x + 40, gy - 3, x + 80, gy + 3, x + 124, gy); g.stroke(); }
