      for (let qy = 0; qy < 2; qy++) for (let qx = 0; qx < 2; qx++) { g.save(); g.beginPath(); g.rect(qx * 128, qy * 128, 128, 128); g.clip(); g.translate(qx * 128 + 64, qy * 128 + 64); g.rotate(((qx + qy) % 2 ? 1 : -1) * PI / 4);
        for (let y = -100; y < 100; y += 16) { g.fillStyle = tone(c, 0.86 + (((y + 100) / 16) % 4) * 0.05); g.fillRect(-100, y, 200, 16); g.fillStyle = 'rgba(40,20,20,0.35)'; g.fillRect(-100, y, 200, 1.2); } g.restore();
        g.fillStyle = 'rgba(30,15,15,0.45)'; g.fillRect(qx * 128, qy * 128, 128, 1.5); g.fillRect(qx * 128, qy * 128, 1.5, 128); }
