    c.fillStyle = '#ffffff'; for (let i = 0; i < 70; i++) c.fillRect((i * 67) % w, (i * 41) % (h * 0.45), 1.5, 1.5);
    const mg = c.createRadialGradient(150, 110, 2, 150, 110, 40); mg.addColorStop(0, 'rgba(255,255,240,1)'); mg.addColorStop(0.3, 'rgba(230,240,255,0.7)'); mg.addColorStop(1, 'rgba(200,220,255,0)'); c.fillStyle = mg; c.beginPath(); c.arc(150, 110, 40, 0, 7); c.fill(); c.fillStyle = '#fffff4'; c.beginPath(); c.arc(150, 110, 10, 0, 7); c.fill();
    c.fillStyle = '#3a4a7a'; c.beginPath(); c.moveTo(0, h * 0.5); c.lineTo(80, h * 0.36); c.lineTo(150, h * 0.46); c.lineTo(200, h * 0.4); c.lineTo(w, h * 0.5); c.fill();
