    k.add(mesh(archG, nightScape, 0, 0.35, 0.03, false));
    const fr = M(0xf4f6fa); for (const x of [-0.9, 0, 0.9]) k.b(0.07, 1.7, 0.08, fr, x, 1.2, 0.05); k.b(1.86, 0.07, 0.08, fr, 0, 2.05, 0.05); k.b(2.0, 0.1, 0.2, fr, 0, 0.32, 0.08);
    const archRing = k.add(mesh(geo('k6ring', () => new THREE.TorusGeometry(0.9, 0.045, 8, 24, PI)), fr, 0, 2.05, 0.05)); for (let i = 1; i < 4; i++) { const a = i / 4 * PI; const sp = k.b(0.04, 0.9, 0.06, fr, Math.cos(a) * 0.45, 2.05 + Math.sin(a) * 0.45, 0.05); sp.rotation.z = a - PI / 2; } k.add(mesh(geo('k6ring2', () => new THREE.TorusGeometry(0.4, 0.03, 8, 20, PI)), fr, 0, 2.05, 0.05));
    const rod = k.c(0.015, 0.015, 2.4, 0x8a8a90, 0, 2.08, 0.18); rod.rotation.z = PI / 2;
    const sheer = new THREE.MeshLambertMaterial({ color: 0xf4f8ff, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false }); for (const sx of [-1, 1]) for (let i = 0; i < 4; i++) { const cu = k.k(0.07, 1.6, sheer, sx * (0.95 + i * 0.07), 1.2, 0.2 + (i % 2) * 0.04); cu.scale.set(1, 1, 0.5); cu.rotation.z = sx * 0.05; }
