  const seascape = pic('seascape', 128, 160, (c, w, h) => { const gr = c.createLinearGradient(0, 0, 0, h); gr.addColorStop(0, '#c8d4d8'); gr.addColorStop(0.5, '#a8b8b0'); gr.addColorStop(1, '#8a9a88'); c.fillStyle = gr; c.fillRect(0, 0, w, h); c.fillStyle = '#6a8a9a'; c.beginPath(); c.moveTo(0, 100); c.bezierCurveTo(40, 70, 80, 110, w, 60); c.lineTo(w, h); c.lineTo(0, h); c.fill(); c.fillStyle = 'rgba(255,255,255,0.6)'; for (let i = 0; i < 30; i++) c.fillRect((i * 23) % w, 80 + (i * 11) % 60, 6, 1.5); c.fillStyle = '#3a4a4a'; for (const x of [20, 34, 44]) { c.fillRect(x, 20, 3, 60); c.beginPath(); c.arc(x + 1, 22, 8, 0, 7); c.fill(); } c.fillStyle = '#c8b890'; c.fillRect(0, 130, w, 30); });
