  def('k5_still_canvas', '정물화 캔버스 (기대 놓은)', 'misc', 700, 0.9, 0.4, g => { const k = K(g); const c1 = k.b(0.75, 0.95, 0.04, 0xe8e0d0, 0, 0.5, 0, 0.01); c1.rotation.x = -0.18; const p = plane(k, 0.7, 0.9, stillLife, 0, 0.5, 0.025); p.rotation.x = -0.18; const c2 = k.b(0.6, 0.8, 0.04, 0xe8e0d0, 0.15, 0.42, -0.1, 0.01); c2.rotation.x = -0.15; }, { tags: ['art'] });
  def('k5_trestle_table', 'A형 작업대 (병 · 팔레트 · 서랍)', 'work', 1600, 1.7, 0.7, g => { const k = K(g), wt = T.woodgrain(WH); k.b(1.7, 0.06, 0.68, wt, 0, 0.8, 0, 0.01); for (const sx of [-1, 1]) for (const sz of [-1, 1]) { const l = k.b(0.05, 0.84, 0.05, wt, sx * 0.62 + sz * 0.1, 0.4, sz * 0.22); l.rotation.x = sz * 0.2; } for (const sx of [-1, 1]) k.b(0.05, 0.05, 0.5, wt, sx * 0.62, 0.3, 0); k.b(1.2, 0.04, 0.5, wt, 0, 0.25, 0); for (let i = 0; i < 5; i++) k.add(mesh(geo('k6jar' + (i % 2), () => new THREE.CylinderGeometry(0.05, 0.05, 0.14 + (i % 2) * 0.06, 12)), glass(0xb8c8c0), -0.45 + i * 0.2, 0.36 + (i % 2) * 0.03, 0)); k.c(0.13, 0.13, 0.012, 0xe8e0d0, 0.1, 0.84, 0.1); for (let i = 0; i < 5; i++) k.s(0.018, [0x3a5a8a, 0xe8d8a0, 0x4a6a4a, 0xc86a5a, 0xf4f4f4][i], 0.05 + Math.cos(i) * 0.07, 0.855, 0.1 + Math.sin(i) * 0.05, 1, 0.4, 1); k.add(mesh(geo('k6flask', () => new THREE.SphereGeometry(0.07, 12, 10)), glass(0xd0e0e8), -0.3, 0.9, -0.1)); k.c(0.015, 0.02, 0.1, 0xd0e0e8, -0.3, 1.0, -0.1); for (let i = 0; i < 6; i++) { const b = k.c(0.006, 0.006, 0.22, 0x5a4a3a, 0.45 + (i % 3) * 0.02, 0.92, -0.18 + ((i / 3) | 0) * 0.02); b.rotation.z = (i - 3) * 0.08; } k.c(0.05, 0.05, 0.1, 0x9a9aa0, 0.45, 0.88, -0.18); k.b(0.3, 0.02, 0.2, 0x4a5a6a, -0.05, 0.84, -0.15, 0.005); }, { use: [{ pose: 'paint', dx: 0, dz: 0.65, face: 180, act: 'paint' }], tags: ['desk', 'art'] });
